/* Кривая опыта (26 ноября, по форме WoW Classic 1.12): сколько опыта нужно с уровня l на l+1. На 1 уровне хватает квеста и пары врагов,
   дальше на уровень нужно всё больше квестов (XP_CURVE.quests). Награда за обычный квест уровня l = XP_TABLE[l] / quests(l).
   Сохранения со старой линейной кривой переводятся при загрузке с сохранением уровня и доли прогресса (script-06, xpCurve: 2). */
const XP_TABLE = [0, 400, 900, 1400, 2100, 2800, 3600, 4500, 5400, 6500, 7600, 8800, 10100, 11400, 12900, 14400, 16000, 17700, 19400, 21300, 23200, 25200, 27300, 29400, 31700, 34000, 36400, 38900, 41400, 44300];
const XP_CURVE = { version: 2, quests: { first: 1.2, perLevel: 0.35 } };
function xpNeed(l) { const L = Math.max(1, Math.min(XP_TABLE.length - 1, Math.round(l))); return XP_TABLE[L]; }
function questsPerLevel(l) { return XP_CURVE.quests.first + XP_CURVE.quests.perLevel * (Math.max(1, l) - 1); }
function xpReward(l) { const L = Math.max(1, Math.round(l)); return L < XP_TABLE.length ? XP_TABLE[L] / questsPerLevel(L) : XP_TABLE[XP_TABLE.length - 1] * Math.pow(1.07, L - XP_TABLE.length + 1) / questsPerLevel(L); }
